151	    /**
152	     * The owner's derived identity key, {@code normalizedTelephone + '|' + (email or empty) + '|' +
153	     * (householdId or empty)}. This single key is the sole criterion for duplicate detection on
154	     * creation: a new owner is rejected with 409 only when its whole identity key equals an existing
155	     * owner's. Because the telephone is part of the key, two members of the same household (same
156	     * {@code householdId}) with different telephones have distinct identity keys and are both
157	     * allowed; only an exact full-key match is a duplicate. The telephone and email components are
158	     * already held in their normalized forms (canonical E.164 and lower-cased) on every write path,
159	     * so the key is comparable across owners. Not persisted: it is computed from the current fields.
160	     */
161	    @Transient
162	    public String getIdentityKey() {
163	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
164	        String emailOrEmpty = this.email == null ? "" : this.email;
