218	     *
219	     * @param name to test
220	     * @return true if pet name is already in use
221	     */
222	    public Pet getPet(String name, boolean ignoreNew) {
223	        name = name.toLowerCase();
224	        for (Pet pet : getPetsInternal()) {
225	            if (!ignoreNew || !pet.isNew()) {
226	                String compName = pet.getName();
227	                compName = compName.toLowerCase();
228	                if (compName.equals(name)) {
229	                    return pet;
