49	@Service
50	public class ClinicServiceImpl implements ClinicService {
51	
52	    /** Maximum number of owners allowed per city. */
53	    private static final long CITY_CAPACITY = 50L;
54	
55	    /** Maximum number of owners that may be created on a single day (by registration date). */
56	    private static final long DAILY_CAPACITY = 100L;
57	
