69	        PetRepository petRepository,
70	        VetRepository vetRepository,
71	        OwnerRepository ownerRepository,
72	        VisitRepository visitRepository,
73	        SpecialtyRepository specialtyRepository,
74	        PetTypeRepository petTypeRepository) {
75	        this.petRepository = petRepository;
76	        this.vetRepository = vetRepository;
77	        this.ownerRepository = ownerRepository;
78	        this.visitRepository = visitRepository;
79	        this.specialtyRepository = specialtyRepository;
80	        this.petTypeRepository = petTypeRepository;
81	    }
