251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        if (owner.isNew()) {
255	            LocalDate effectiveDate = owner.getRegistrationDate() != null
256	                ? owner.getRegistrationDate()
257	                : LocalDate.now();
258	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
259	            if (owner.getCustomerCode() == null) {
260	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
261	            }
262	            if (owner.getNamesakeCount() == null) {
263	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
264	            }
265	        }
