374	        try {
375	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
376	            StringBuilder sb = new StringBuilder(32);
377	            for (int i = 0; i < 8; i++) {
